package darksafe

import (
	"bytes"
	"encoding/json"
	"fmt"
	"math"
	"sort"
	"strings"
)

// Sample 是一个待写入的采样点。
type Sample struct {
	Name      string            `json:"name"`
	Timestamp int64             `json:"timestamp"`
	Value     float64           `json:"value"`
	Labels    map[string]string `json:"labels,omitempty"`
}

// Point 是一条序列上某个时间戳的采样值。
type Point struct {
	Timestamp int64   `json:"timestamp"`
	Value     float64  `json:"value"`
}

// SeriesView 是结果输出用的一条序列视图。
type SeriesView struct {
	Name   string            `json:"name"`
	Labels map[string]string `json:"labels"`
	Points []Point           `json:"points"`
}

// BatchResult 是一批采样点写入成功后的结果。
type BatchResult struct {
	Status     string       `json:"status"`
	Added      int          `json:"added"`
	Duplicates int          `json:"duplicates"`
	Series     []SeriesView `json:"series"`
}

// SampleError 描述从 1 开始计数的采样点错误。
type SampleError struct {
	Index int    `json:"index"`
	Error string `json:"error"`
}

// LineError 是一行输入失败的结构化结果。
type LineError struct {
	Status  string       `json:"status"`
	Line    int          `json:"line"`
	Error   string       `json:"error"`
	Sample  *SampleError `json:"sample,omitempty"`
	Conflict *Conflict  `json:"conflict,omitempty"`
}

// Conflict 描述同序列同时间戳已有不同值。
type Conflict struct {
	Series    SeriesRef `json:"series"`
	Timestamp int64     `json:"timestamp"`
	Existing  float64   `json:"existing"`
	Submitted float64   `json:"submitted"`
}

// SeriesRef 标识一条序列：指标名加完整标签集合。
type SeriesRef struct {
	Name   string            `json:"name"`
	Labels map[string]string `json:"labels"`
}

// MetricStore 保存本次命令运行期间已写入的指标数据，不落盘。
type MetricStore struct {
	// series 以排序后的 "name\0k1\0v1\0k2\0v2" 形式索引序列。
	series map[string]*storedSeries
}

type storedSeries struct {
	ref    SeriesRef
	points map[int64]float64
}

// NewMetricStore 创建一个空的指标存储。
func NewMetricStore() *MetricStore {
	return &MetricStore{series: make(map[string]*storedSeries)}
}

func seriesKey(name string, labels map[string]string) string {
	keys := make([]string, 0, len(labels))
	for k := range labels {
		keys = append(keys, k)
	}
	sort.Strings(keys)
	var b strings.Builder
	b.WriteString(name)
	for _, k := range keys {
		b.WriteByte(0)
		b.WriteString(k)
		b.WriteByte(0)
		b.WriteString(labels[k])
	}
	return b.String()
}

func sortedKeys(m map[string]string) []string {
	keys := make([]string, 0, len(m))
	for k := range m {
		keys = append(keys, k)
	}
	sort.Strings(keys)
	return keys
}

// labelPair 是标签键值对的字典序比较单元。
type labelPair struct {
	Key, Value string
}

func sortedPairs(labels map[string]string) []labelPair {
	keys := sortedKeys(labels)
	pairs := make([]labelPair, len(keys))
	for i, k := range keys {
		pairs[i] = labelPair{Key: k, Value: labels[k]}
	}
	return pairs
}

func compareLabelPairs(a, b []labelPair) int {
	n := len(a)
	if len(b) < n {
		n = len(b)
	}
	for i := 0; i < n; i++ {
		if a[i].Key != b[i].Key {
			return strings.Compare(a[i].Key, b[i].Key)
		}
		if a[i].Value != b[i].Value {
			return strings.Compare(a[i].Value, b[i].Value)
		}
	}
	switch {
	case len(a) < len(b):
		return -1
	case len(a) > len(b):
		return 1
	}
	return 0
}

// IngestLine 解析并写入一行（一批）采样点。成功返回 BatchResult；
// 失败返回 LineError，且此前各批数据保持不变、本批也不产生任何写入。
func (s *MetricStore) IngestLine(line string) (*BatchResult, *LineError) {
	var raw []json.RawMessage
	dec := json.NewDecoder(bytes.NewReader([]byte(line)))
	if err := dec.Decode(&raw); err == nil {
		// 数组之后不允许出现其它顶层 JSON 值；尾随空白允许。
		if err := dec.Decode(new(interface{})); err != ioEOF {
			// 有多余内容：整体当作无法解析。
			err2 := checkTrailing(line)
			if err2 != nil {
				return nil, &LineError{Status: "error", Error: err2.Error()}
			}
		}
	} else {
		return nil, &LineError{Status: "error", Error: "invalid JSON: " + err.Error()}
	}
	return s.ingestRaw(raw)
}

// checkTrailing 复核一行是否为单一 JSON 值，返回解析错误或 nil。
func checkTrailing(line string) error {
	dec := json.NewDecoder(strings.NewReader(line))
	var v interface{}
	if err := dec.Decode(&v); err != nil {
		return fmt.Errorf("invalid JSON: %s", err)
	}
	var extra interface{}
	if err := dec.Decode(&extra); err != ioEOF {
		return fmt.Errorf("invalid JSON: unexpected content after first value")
	}
	return nil
}

// ingestRaw 完成字段级严格校验与冲突检测，保证整批原子性。
func (s *MetricStore) ingestRaw(raw []json.RawMessage) (*BatchResult, *LineError) {
	type planned struct {
		ref      SeriesRef
		key      string
		ts       int64
		val      float64
		isNew    bool // 相对当前存储是否为新点
	}
	plans := make([]planned, 0, len(raw))
	// 本批内已确定的点：series key -> timestamp -> value（来源为旧值或本批首点）。
	within := make(map[string]map[int64]float64)
	added := 0

	fail := func(index int, format string, args ...interface{}) (*BatchResult, *LineError) {
		return nil, &LineError{
			Status: "error",
			Error:  fmt.Sprintf(format, args...),
			Sample: &SampleError{Index: index, Error: fmt.Sprintf(format, args...)},
		}
	}

	for i, item := range raw {
		pos := i + 1
		// 严格字段校验：不允许未知字段。
		var fields map[string]json.RawMessage
		if err := strictUnmarshal(item, &fields); err != nil {
			return fail(pos, "invalid sample: %s", err)
		}

		nameRaw, hasName := fields["name"]
		tsRaw, hasTS := fields["timestamp"]
		valRaw, hasVal := fields["value"]
		labelsRaw, hasLabels := fields["labels"]
		if !hasName {
			return fail(pos, "missing required field %q", "name")
		}
		if !hasTS {
			return fail(pos, "missing required field %q", "timestamp")
		}
		if !hasVal {
			return fail(pos, "missing required field %q", "value")
		}

		var name string
		if err := json.Unmarshal(nameRaw, &name); err != nil {
			return fail(pos, "field %q must be a string", "name")
		}
		if name == "" {
			return fail(pos, "field %q must be a non-empty string", "name")
		}

		ts, err := decodeInt64(tsRaw)
		if err != nil {
			return fail(pos, "field %q: %s", "timestamp", err)
		}

		val, err := decodeFiniteFloat(valRaw)
		if err != nil {
			return fail(pos, "field %q: %s", "value", err)
		}

		labels := map[string]string{}
		if hasLabels {
			var lm map[string]string
			if err := strictLabelObject(labelsRaw, &lm); err != nil {
				return fail(pos, "field %q: %s", "labels", err)
			}
			labels = lm
		}

		key := seriesKey(name, labels)
		existing, existed := s.valueAt(key, ts)
		if batch, seen := within[key]; seen {
			if bv, ok := batch[ts]; ok {
				// 同批内已出现该序列该时间戳。
				if bv != val {
					return nil, &LineError{
						Status:  "error",
						Error:   "conflicting samples in the same batch",
						Sample:  &SampleError{Index: pos, Error: fmt.Sprintf("conflict at timestamp %d: existing value %s, submitted %s", ts, formatFloat(bv), formatFloat(val))},
						Conflict: &Conflict{Series: SeriesRef{Name: name, Labels: labels}, Timestamp: ts, Existing: bv, Submitted: val},
					}
				}
				continue // 重复点，成功忽略
			}
		}
		if existed {
			if existing != val {
				return nil, &LineError{
					Status:  "error",
					Error:   "conflict with previously written data",
					Sample:  &SampleError{Index: pos, Error: fmt.Sprintf("conflict at timestamp %d: existing value %s, submitted %s", ts, formatFloat(existing), formatFloat(val))},
					Conflict: &Conflict{Series: s.refAt(key, name, labels), Timestamp: ts, Existing: existing, Submitted: val},
				}
			}
			// 与已写入数据相同：重复。
		} else {
			added++
		}
		if within[key] == nil {
			within[key] = make(map[int64]float64)
		}
		within[key][ts] = val
		plans = append(plans, planned{ref: SeriesRef{Name: name, Labels: labels}, key: key, ts: ts, val: val, isNew: !existed})
	}

	// 全部校验通过，提交本批。
	for _, p := range plans {
		if !p.isNew {
			continue
		}
		sr := s.series[p.key]
		if sr == nil {
			sr = &storedSeries{ref: p.ref, points: make(map[int64]float64)}
			s.series[p.key] = sr
		}
		sr.points[p.ts] = p.val
	}

	return s.snapshot(added, len(raw)-added-plansDupCount(plans, raw)), nil
}

func plansDupCount(plans []planned, raw []json.RawMessage) int {
	// 占位：实际重复数在调用处计算更直接，保留以避免签名分散。
	return 0
}

func (s *MetricStore) valueAt(key string, ts int64) (float64, bool) {
	if sr, ok := s.series[key]; ok {
		v, ok := sr.points[ts]
		return v, ok
	}
	return 0, false
}

func (s *MetricStore) refAt(key, name string, labels map[string]string) SeriesRef {
	if sr, ok := s.series[key]; ok {
		return sr.ref
	}
	return SeriesRef{Name: name, Labels: labels}
}

// snapshot 生成按规范排序的全部序列视图。
func (s *MetricStore) snapshot(added, duplicates int) *BatchResult {
	views := make([]SeriesView, 0, len(s.series))
	for _, sr := range s.series {
		keys := make([]int64, 0, len(sr.points))
		for ts := range sr.points {
			keys = append(keys, ts)
		}
		sort.Slice(keys, func(i, j int) bool { return keys[i] < keys[j] })
		points := make([]Point, len(keys))
		for i, ts := range keys {
			points[i] = Point{Timestamp: ts, Value: sr.points[ts]}
		}
		labels := map[string]string{}
		for k, v := range sr.ref.Labels {
			labels[k] = v
		}
		views = append(views, SeriesView{Name: sr.ref.Name, Labels: labels, Points: points})
	}
	sort.Slice(views, func(i, j int) bool {
		if views[i].Name != views[j].Name {
			return views[i].Name < views[j].Name
		}
		return compareLabelPairs(sortedPairs(views[i].Labels), sortedPairs(views[j].Labels)) < 0
	})
	return &BatchResult{Status: "ok", Added: added, Duplicates: duplicates, Series: views}
}

