		n = len(b)
	}
	for i := 0; i < n; i++ {
		if a[i].Key != b[i].Key {
			return strings.Compare(a[i].Key, b[i].Key)
		}
		if a[i].Value != b[i].Value {
			return strings.Compare(a[i].Value, b[i].Value)
		}
	}
	switch {
	case len(a) < len(b):
		return -1
	case len(a) > len(b):
		return 1
	}
	return 0
}

var (
	jsonIntegerRE = regexp.MustCompile(`^-?(0|[1-9][0-9]*)$`)
	jsonNumberRE  = regexp.MustCompile(`^-?(0|[1-9][0-9]*)(\.[0-9]+)?([eE][+-]?[0-9]+)?$`)
)

// rawSample 逐字段接收原始 JSON，便于做严格类型校验。
type rawSample struct {
	Name      json.RawMessage `json:"name"`
	Timestamp json.RawMessage `json:"timestamp"`
	Value     json.RawMessage `json:"value"`
	Labels    json.RawMessage `json:"labels"`
}

func parseLineError(err error) *LineError {
	return &LineError{Status: "error", Error: "invalid JSON: " + err.Error()}
}

// IngestLine 解析并写入一行（一批）采样点。成功返回 BatchResult；
// 失败返回 *LineError，此时此前各批数据保留、本批不写入任何数据。
func (s *MetricStore) IngestLine(line string) (*BatchResult, *LineError) {
	dec := json.NewDecoder(strings.NewReader(line))
	var top json.RawMessage
	if err := dec.Decode(&top); err != nil {
		return nil, parseLineError(err)
	}
	// 第一个 JSON 值之后只允许文件结束（空白由 Decoder 跳过）。
	if err := dec.Decode(new(json.RawMessage)); err != io.EOF {
		if err == nil {
			err = fmt.Errorf("unexpected content after the JSON array")
		}
		return nil, parseLineError(err)
	}
	trimmed := strings.TrimSpace(string(top))
	if len(trimmed) == 0 || trimmed[0] != '[' {
		return nil, parseLineError(fmt.Errorf("input must be a JSON array of samples"))
	}
	var items []json.RawMessage
	if err := json.Unmarshal(top, &items); err != nil {
		return nil, parseLineError(err)
	}
	return s.ingestItems(items)
}

// ingestItems 完成字段级严格校验与冲突检测，保证整批原子提交。
func (s *MetricStore) ingestItems(items []json.RawMessage) (*BatchResult, *LineError) {
	type pending struct {
		id  seriesID
		ref SeriesRef
		ts  int64
		val float64
	}

	added := 0
	// 本批已确定身份的点（含与已写入数据重复的点），用于批内去重与冲突检测。
	seen := make(map[seriesID]map[int64]float64)
	// 仅记录需要落盘的新增点，校验全部通过后统一提交。
	commits := make([]pending, 0, len(items))

	failAt := func(index int, msg string) (*BatchResult, *LineError) {
		return nil, &LineError{Status: "error", Index: index, Error: msg}
	}
	conflictAt := func(index int, ref SeriesRef, ts int64, existing, submitted float64) (*BatchResult, *LineError) {
		return nil, &LineError{
			Status: "error",
			Index:  index,
			Error:  fmt.Sprintf("conflict: series %s at timestamp %d has existing value %s, submitted %s", ref, ts, formatFloat(existing), formatFloat(submitted)),
			Conflict: &Conflict{
				Series:    ref,
				Timestamp: ts,
				Existing:  existing,
				Submitted: submitted,
			},
		}
	}

	for i, item := range items {
		pos := i + 1
		itemStr := strings.TrimSpace(string(item))
		if len(itemStr) == 0 || itemStr[0] != '{' {
			return failAt(pos, "each sample must be a JSON object")
		}

		dec := json.NewDecoder(bytes.NewReader(item))
		dec.DisallowUnknownFields()
		var rs rawSample
		if err := dec.Decode(&rs); err != nil {
			return failAt(pos, "invalid sample: "+err.Error())
		}

		if len(rs.Name) == 0 {
			return failAt(pos, `missing required field "name"`)
		}
		if len(rs.Timestamp) == 0 {
			return failAt(pos, `missing required field "timestamp"`)
		}
		if len(rs.Value) == 0 {
			return failAt(pos, `missing required field "value"`)
		}

		var name string
		if err := json.Unmarshal(rs.Name, &name); err != nil {
			return failAt(pos, `field "name" must be a string`)
		}
		if name == "" {
			return failAt(pos, `field "name" must be a non-empty string`)
		}

		ts, err := decodeInt64(rs.Timestamp)
		if err != nil {
			return failAt(pos, fmt.Sprintf(`field "timestamp": %s`, err))
		}

		val, err := decodeFiniteFloat(rs.Value)
		if err != nil {
			return failAt(pos, fmt.Sprintf(`field "value": %s`, err))
		}

		labels := map[string]string{}
		if len(rs.Labels) > 0 {
			labels, err = decodeLabels(rs.Labels)
			if err != nil {
				return failAt(pos, fmt.Sprintf(`field "labels": %s`, err))
			}
		}

		id := seriesIDOf(name, labels)
		ref := SeriesRef{Name: name, Labels: labels}

		if byTS, ok := seen[id]; ok {
			if old, ok := byTS[ts]; ok {
				if old != val {
					return conflictAt(pos, ref, ts, old, val)
				}
				continue // 同批重复点
			}
		}
		if sr, ok := s.series[id]; ok {
			if old, ok := sr.points[ts]; ok {
				if old != val {
					return conflictAt(pos, sr.ref, ts, old, val)
				}
				// 与此前批次相同：重复，成功忽略。
				if seen[id] == nil {
					seen[id] = map[int64]float64{}
				}
				seen[id][ts] = val
				continue
			}
		}

		added++
		if seen[id] == nil {
			seen[id] = map[int64]float64{}
		}
		seen[id][ts] = val
		commits = append(commits, pending{id: id, ref: ref, ts: ts, val: val})
	}

	// 全部采样点合法且无冲突，原子提交本批新增点。
	for _, p := range commits {
		sr := s.series[p.id]
		if sr == nil {
			sr = &storedSeries{ref: p.ref, points: map[int64]float64{}}
			s.series[p.id] = sr
		}
		sr.points[p.ts] = p.val
	}

	return s.snapshot(added, len(items)-added), nil
}

func decodeInt64(raw json.RawMessage) (int64, error) {
	s := strings.TrimSpace(string(raw))
	if !jsonIntegerRE.MatchString(s) {
		return 0, fmt.Errorf("must be a JSON integer")
	}
	v, err := strconv.ParseInt(s, 10, 64)
	if err != nil {
		return 0, fmt.Errorf("must be within int64 range")
	}
	return v, nil
}

func decodeFiniteFloat(raw json.RawMessage) (float64, error) {
	s := strings.TrimSpace(string(raw))
	if !jsonNumberRE.MatchString(s) {
		return 0, fmt.Errorf("must be a JSON number")
	}
	v, err := strconv.ParseFloat(s, 64)
	if err != nil || math.IsInf(v, 0) || math.IsNaN(v) {
		return 0, fmt.Errorf("must be a finite number representable as float64")
	}
	return v, nil
}

func decodeLabels(raw json.RawMessage) (map[string]string, error) {
	s := strings.TrimSpace(string(raw))
	if len(s) == 0 || s[0] != '{' {
		return nil, fmt.Errorf("must be an object mapping string keys to string values")
	}
	var m map[string]json.RawMessage
	if err := json.Unmarshal(raw, &m); err != nil {
		return nil, fmt.Errorf("must be an object mapping string keys to string values")
	}
	out := make(map[string]string, len(m))
	for _, k := range sortedKeys(m) {
		if k == "" {
			return nil, fmt.Errorf("label keys must be non-empty strings")
		}
		var v string
		if err := json.Unmarshal(m[k], &v); err != nil {
			return nil, fmt.Errorf("value of label %q must be a string", k)
		}
		out[k] = v
	}
	return out, nil
}

// formatFloat 以 JSON 数值风格格式化 float64：1 与 1.0 都显示为 1。
func formatFloat(v float64) string {
	return strconv.FormatFloat(v, 'g', -1, 64)
}

// String 让冲突错误中的序列身份可读：name{k=v,...}，标签按键排序。
func (r SeriesRef) String() string {
	var b strings.Builder
	b.WriteString(r.Name)
	b.WriteByte('{')
	for i, p := range sortedPairs(r.Labels) {
		if i > 0 {
			b.WriteByte(',')
		}
		fmt.Fprintf(&b, "%s=%s", p.Key, p.Value)
	}
	b.WriteByte('}')
	return b.String()
}

// snapshot 生成按规范排序的全部序列视图。
func (s *MetricStore) snapshot(added, duplicates int) *BatchResult {
	views := make([]SeriesView, 0, len(s.series))
	for _, sr := range s.series {
		tsList := make([]int64, 0, len(sr.points))
		for ts := range sr.points {
			tsList = append(tsList, ts)
		}
		sort.Slice(tsList, func(i, j int) bool { return tsList[i] < tsList[j] })
		points := make([]Point, len(tsList))
		for i, ts := range tsList {
			points[i] = Point{Timestamp: ts, Value: sr.points[ts]}
		}
		labels := make(map[string]string, len(sr.ref.Labels))
		for k, v := range sr.ref.Labels {
			labels[k] = v
		}
		views = append(views, SeriesView{Name: sr.ref.Name, Labels: labels, Points: points})
	}
	sort.Slice(views, func(i, j int) bool {
		if views[i].Name != views[j].Name {
			return views[i].Name < views[j].Name
		}
		return compareLabelPairs(sortedPairs(views[i].Labels), sortedPairs(views[j].Labels)) < 0
	})
	return &BatchResult{Status: "ok", Added: added, Duplicates: duplicates, Series: views}
}

